24	// ---- Internals ----
25	
26	function getToolUseBlocks(event: SessionEvent): ToolUseBlock[] {
27	  if (event.type !== 'content') return []
28	  const data = event.data as { blocks?: ContentBlock[] }
29	  if (!data.blocks) return []
30	  return data.blocks.filter((b): b is ToolUseBlock => b.type === 'tool_use')
