34	  const tools = getToolUseBlocks(event)
35	  if (tools.length === 0) return false
36	  return tools.every((t) => classifyTool(t.name, t.input).isCollapsible)
37	}
38	
39	function buildSummary(counts: { read: number; search: number; list: number }): string {
40	  const parts: string[] = []
41	
42	  if (counts.read > 0) {
43	    parts.push(`Read ${counts.read} file${counts.read !== 1 ? 's' : ''}`)
44	  }
45	  if (counts.search > 0) {
46	    parts.push(`searched ${counts.search} pattern${counts.search !== 1 ? 's' : ''}`)
47	  }
48	  if (counts.list > 0) {
49	    parts.push(`listed ${counts.list} director${counts.list !== 1 ? 'ies' : 'y'}`)
50	  }
51	
52	  if (parts.length > 0) {
53	    parts[0] = parts[0].charAt(0).toUpperCase() + parts[0].slice(1)
54	  }
55	
56	  return parts.join(', ') || 'Explored codebase'
57	}
58	
59	function flushGroup(
60	  pendingEvents: SessionEvent[],
61	  classifications: ToolClassification[],
62	  output: GroupedEvent[],
63	): void {
64	  if (classifications.length < 2) {
65	    output.push(...pendingEvents)
66	    return
67	  }
68	
69	  const counts = { read: 0, search: 0, list: 0 }
70	  const paths = new Set<string>()
71	
72	  for (const c of classifications) {
73	    switch (c.category) {
74	      case 'read':
75	        if (c.name === 'LS' || c.name === 'ListMcpResourcesTool') {
76	          counts.list++
77	        } else {
78	          counts.read++
79	        }
80	        break
81	      case 'search':
82	        counts.search++
83	        break
84	    }
85	    if (c.detail) paths.add(c.detail)
86	  }
87	
88	  output.push({
89	    type: 'collapsed',
90	    events: [...pendingEvents],
91	    summary: buildSummary(counts),
92	    counts,
93	    paths: [...paths],
94	  })
95	}
